//! Rust reference server skeleton for the differential harness (UNINSTRUMENTED:
//! there is no Rust AgentCat SDK yet). It serves the exact tool contract the
//! TS reference server advertises, loaded from tool-contract.json (generated by
//! running the TS server without track()), so host-SDK differences between
//! rmcp and the TS MCP SDK can be measured before any AgentCat code exists.
use rmcp::{
    ErrorData as McpError, RoleServer, ServerHandler, ServiceExt,
    model::{
        CallToolRequestParams, CallToolResponse, CallToolResult, ContentBlock as Content, Implementation,
        ListToolsResult, PaginatedRequestParams, ServerCapabilities, ServerConfig, Tool,
    },
    service::RequestContext,
};
use serde_json::{Value, json};

struct RefServer {
    tools: Vec<Tool>,
}

impl ServerHandler for RefServer {
    fn get_info(&self) -> ServerConfig {
        ServerConfig::new(ServerCapabilities::builder().enable_tools().build())
            .with_server_info(Implementation::new("diff-ref-server", "1.0.0"))
    }

    async fn list_tools(
        &self,
        _request: Option<PaginatedRequestParams>,
        _context: RequestContext<RoleServer>,
    ) -> Result<ListToolsResult, McpError> {
        Ok(serde_json::from_value(json!({ "tools": self.tools })).expect("tools"))
    }

    async fn call_tool(
        &self,
        request: CallToolRequestParams,
        _context: RequestContext<RoleServer>,
    ) -> Result<CallToolResponse, McpError> {
        let args = request.arguments.clone().unwrap_or_default();
        let msg = args.get("msg").and_then(Value::as_str).unwrap_or_default().to_string();
        let result = match request.name.as_ref() {
            "echo" => CallToolResult::success(vec![Content::text(msg)]),
            "structured" => {
                let mut r = CallToolResult::success(vec![Content::text(msg.clone())]);
                r.structured_content = Some(json!({ "echoed": msg }));
                r
            }
            "boom" => return Err(McpError::internal_error("boom", None)),
            "tool_error" => CallToolResult::error(vec![Content::text("handled failure")]),
            "big" => {
                let size = args.get("size").and_then(Value::as_u64).unwrap_or(0) as usize;
                CallToolResult::success(vec![Content::text("x".repeat(size))])
            }
            "emit_custom" => CallToolResult::success(vec![Content::text("published")]),
            other => {
                return Err(McpError::invalid_params(format!("Tool {other} not found"), None));
            }
        };
        Ok(result.into())
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let contract = std::env::var("TOOL_CONTRACT").unwrap_or_else(|_| "tool-contract.json".into());
    let tools: Vec<Tool> = serde_json::from_str(&std::fs::read_to_string(contract)?)?;
    let mode = std::env::args().nth(1).unwrap_or_else(|| "stdio".into());
    if mode != "stdio" {
        return Err("spike skeleton only implements stdio".into());
    }
    let service = RefServer { tools }.serve(rmcp::transport::stdio()).await?;
    service.waiting().await?;
    Ok(())
}
